import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  copyFileSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const dashboardRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const agentRoot = resolve(dashboardRoot, "..");
const outputDir = resolve(dashboardRoot, "public");
const output = resolve(outputDir, "prostar-agent.tgz");
const checksumOutput = resolve(outputDir, "prostar-agent.tgz.sha256");
const legacyOutput = resolve(outputDir, "screen-viewer-agent.tgz");

const files = [
  "package.json",
  "package-lock.json",
  "tsconfig.json",
  "tsconfig.build.json",
  ".env.example",
  ".npmrc",
  "src",
  "public",
  "scripts",
  "launchd",
];

mkdirSync(outputDir, { recursive: true });
const result = spawnSync("tar", ["-czf", output, ...files], {
  cwd: agentRoot,
  stdio: "inherit",
});

if (result.status !== 0) {
  throw new Error(`Could not build agent bundle (tar exited ${result.status})`);
}

const checksum = createHash("sha256")
  .update(readFileSync(output))
  .digest("hex");
writeFileSync(checksumOutput, `${checksum}  prostar-agent.tgz\n`);

// Keep ten-minute setup links generated by the previous dashboard build valid
// through the rename rollout.
copyFileSync(output, legacyOutput);
